const entrada = $input.first().json || {};

const body =
  entrada.body &&
  typeof entrada.body === 'object' &&
  !Array.isArray(entrada.body)
    ? entrada.body
    : entrada;

const headers =
  entrada.headers &&
  typeof entrada.headers === 'object' &&
  !Array.isArray(entrada.headers)
    ? entrada.headers
    : {};

const normalizarTexto = (valor) =>
  typeof valor === 'string' ? valor.trim() : '';

const mensaje = normalizarTexto(
  body.mensaje ||
  body.message ||
  body.text
);

const idCliente = normalizarTexto(body.idCliente);
const idServicio = normalizarTexto(body.idServicio);
const idStaff = normalizarTexto(body.idStaff);
const servicio = normalizarTexto(body.servicio);
const fecha = normalizarTexto(body.fecha);
const hora = normalizarTexto(body.hora);

const sessionId =
  normalizarTexto(body.sessionId) ||
  `cliente-${idCliente || 'anonimo'}`;

// Obtener Authorization desde los headers del Webhook.
// Este token se usará después para llamar al backend.
// IMPORTANTE: no se envía dentro del prompt a la IA.
let authorization =
  normalizarTexto(headers.authorization) ||
  normalizarTexto(headers.Authorization);

if (authorization && !authorization.toLowerCase().startsWith('bearer ')) {
  authorization = `Bearer ${authorization}`;
}

// Fecha actual en Chile.
const partesFecha = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'America/Santiago',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
}).formatToParts(new Date());

const year =
  partesFecha.find((parte) => parte.type === 'year')?.value || '';

const month =
  partesFecha.find((parte) => parte.type === 'month')?.value || '';

const day =
  partesFecha.find((parte) => parte.type === 'day')?.value || '';

const fechaActualChile = `${year}-${month}-${day}`;

const estructura = JSON.stringify(
  {
    intencion: 'agendar_cita',
    servicio: '',
    fecha: '',
    hora: '',
    idCliente: '',
    idServicio: '',
    idStaff: '',
    datosFaltantes: [],
  },
  null,
  2
);

const prompt = [
  'Eres el asistente de agendamiento de Style & Beauty.',
  '',
  'Tu única tarea en esta etapa es interpretar la solicitud del cliente y extraer los datos necesarios para iniciar una reserva.',
  '',
  'Devuelve únicamente un objeto JSON válido.',
  'No uses Markdown.',
  'No uses bloques de código.',
  'No agregues explicaciones fuera del JSON.',
  '',
  'Mensaje del cliente:',
  mensaje || '(sin mensaje)',
  '',
  'Datos entregados por el sistema. Debes conservarlos cuando no estén vacíos:',
  `idCliente: ${idCliente}`,
  `idServicio: ${idServicio}`,
  `idStaff: ${idStaff}`,
  `servicio: ${servicio}`,
  `fecha: ${fecha}`,
  `hora: ${hora}`,
  '',
  `Fecha actual en Chile: ${fechaActualChile}`,
  '',
  'Responde exactamente con esta estructura:',
  estructura,
  '',
  'Reglas:',
  '- La intención para este flujo es agendar_cita.',
  '- Copia exactamente los identificadores entregados por el sistema; nunca inventes UUID.',
  '- Si el sistema ya entregó idCliente, idServicio o idStaff, conserva esos valores.',
  '- Si el sistema ya entregó servicio, fecha u hora, conserva esos valores.',
  '- Si el cliente menciona un servicio, copia su nombre sin inventar otro.',
  '- Usa fecha en formato YYYY-MM-DD.',
  '- Si dice hoy, usa la fecha actual de Chile.',
  '- Si dice mañana, calcula el día siguiente desde la fecha actual de Chile.',
  '- Usa hora en formato HH:mm de 24 horas.',
  '- Convierte expresiones como 3 de la tarde a 15:00.',
  '- Si falta servicio y también falta idServicio, agrega servicio a datosFaltantes.',
  '- Si falta fecha, agrega fecha a datosFaltantes.',
  '- Si falta una hora exacta, agrega hora a datosFaltantes.',
  '- Si falta idCliente, agrega cliente a datosFaltantes.',
  '- idStaff no es obligatorio en esta etapa y nunca debe agregarse a datosFaltantes.',
  '- No confirmes disponibilidad.',
  '- No confirmes creación de cita.',
  '- No confirmes pago.',
  '- La reserva queda confirmada únicamente cuando Webpay aprueba el pago.',
].join('\n');

return [
  {
    json: {
      ...entrada,

      mensaje,
      idCliente,
      idServicio,
      idStaff,
      servicio,
      fecha,
      hora,
      sessionId,
      fechaActualChile,

      authorization,

      prompt,
      chatInput: prompt,
    },
  },
];

const entrada = $input.first().json || {};

// Obtener la respuesta del AI Agent.
// Normalmente viene en entrada.output.
let output =
  entrada.output ??
  entrada.text ??
  entrada.response ??
  entrada.content ??
  '{}';

let data;

try {
  if (typeof output === 'string') {
    output = output
      .trim()
      .replace(/^```json\s*/i, '')
      .replace(/^```\s*/i, '')
      .replace(/\s*```$/i, '');

    data = JSON.parse(output);
  } else {
    data = output;
  }

  if (!data || typeof data !== 'object' || Array.isArray(data)) {
    throw new Error('La respuesta del agente no es un objeto JSON válido');
  }
} catch (error) {
  data = {
    intencion: 'agendar_cita',
    servicio: '',
    fecha: '',
    hora: '',
    idCliente: '',
    idServicio: '',
    idStaff: '',
    datosFaltantes: []
  };
}

// Función para limpiar textos.
const normalizarTexto = (valor) => {
  return typeof valor === 'string'
    ? valor.trim()
    : '';
};

// Elegir el primer valor válido.
const primerValor = (...valores) => {
  for (const valor of valores) {
    const texto = normalizarTexto(valor);

    if (texto) {
      return texto;
    }
  }

  return '';
};

// Mantener la intención fija para este flujo.
data.intencion = normalizarTexto(data.intencion).toLowerCase() || 'agendar_cita';

if (data.intencion !== 'agendar_cita') {
  data.intencion = 'agendar_cita';
}

// IMPORTANTE:
// Estos valores vienen desde el sistema y tienen prioridad.
// entrada.idClienteSistema, entrada.idServicioSistema, etc.
// vienen desde el nodo "Adjuntar contexto sistema".
data.idCliente = primerValor(
  entrada.idClienteSistema,
  entrada.idCliente,
  data.idCliente
);

data.idServicio = primerValor(
  entrada.idServicioSistema,
  entrada.idServicio,
  data.idServicio
);

data.idStaff = primerValor(
  entrada.idStaffSistema,
  entrada.idStaff,
  data.idStaff
);

data.servicio = primerValor(
  entrada.servicioSistema,
  entrada.servicio,
  data.servicio
);

data.fecha = primerValor(
  entrada.fechaSistema,
  entrada.fecha,
  data.fecha
);

data.hora = primerValor(
  entrada.horaSistema,
  entrada.hora,
  data.hora
);

data.sessionId = primerValor(
  entrada.sessionId,
  data.sessionId,
  data.idCliente ? `cliente-${data.idCliente}` : 'cliente-anonimo'
);

// Mantener el token Authorization para los nodos HTTP posteriores.
// Este campo es clave para Crear cita y Webpay.
data.authorization = primerValor(
  entrada.authorization,
  data.authorization
);

// Si llega el token sin Bearer, se lo agregamos.
if (
  data.authorization &&
  !data.authorization.toLowerCase().startsWith('bearer ')
) {
  data.authorization = `Bearer ${data.authorization}`;
}

// Validar fecha YYYY-MM-DD.
const fechaValida = (valor) => {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(valor)) {
    return false;
  }

  const [year, month, day] = valor.split('-').map(Number);
  const fecha = new Date(Date.UTC(year, month - 1, day));

  return (
    fecha.getUTCFullYear() === year &&
    fecha.getUTCMonth() === month - 1 &&
    fecha.getUTCDate() === day
  );
};

if (data.fecha && !fechaValida(data.fecha)) {
  data.fecha = '';
}

// Validar hora HH:mm.
if (data.hora && !/^([01]\d|2[0-3]):[0-5]\d$/.test(data.hora)) {
  data.hora = '';
}

// Recalcular datos faltantes desde cero.
const datosFaltantes = [];

if (!data.idCliente) {
  datosFaltantes.push('cliente');
}

if (!data.servicio && !data.idServicio) {
  datosFaltantes.push('servicio');
}

if (!data.fecha) {
  datosFaltantes.push('fecha');
}

if (!data.hora) {
  datosFaltantes.push('hora');
}

// idStaff NO es obligatorio en esta etapa.
// Si viene, se usa. Si no viene, se consulta después.
data.datosFaltantes = datosFaltantes;

return [
  {
    json: data
  }
];

const datosCita = $('Normalizar datos').first().json || {};
const servicios = [];

const agregarServicios = (valor) => {
  if (Array.isArray(valor)) {
    servicios.push(...valor.filter(Boolean));
    return true;
  }

  return false;
};

for (const item of $input.all()) {
  const json = item.json;

  if (agregarServicios(json)) continue;
  if (!json || typeof json !== 'object') continue;
  if (agregarServicios(json.body)) continue;
  if (agregarServicios(json.data)) continue;
  if (agregarServicios(json.content)) continue;
  if (agregarServicios(json.items)) continue;
  if (agregarServicios(json.servicios)) continue;

  servicios.push(json);
}

const normalizar = (valor) =>
  typeof valor === 'string'
    ? valor
        .toLowerCase()
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g, '')
        .trim()
    : '';

const nombreBuscado = normalizar(datosCita.servicio);
const idServicioBuscado = normalizar(datosCita.idServicio);

if (!nombreBuscado && !idServicioBuscado) {
  return [
    {
      json: {
        ...datosCita,
        servicioEncontrado: false,
        mensaje: 'Debes indicar qué servicio quieres reservar.',
      },
    },
  ];
}

const obtenerId = (servicio) =>
  servicio?.id_servicio || servicio?.idServicio || servicio?.id || '';

let servicioEncontrado = servicios.find((servicio) => {
  return idServicioBuscado && normalizar(String(obtenerId(servicio))) === idServicioBuscado;
});

if (!servicioEncontrado && nombreBuscado) {
  servicioEncontrado = servicios.find(
    (servicio) => normalizar(servicio?.nombre) === nombreBuscado,
  );
}

if (!servicioEncontrado && nombreBuscado) {
  servicioEncontrado = servicios.find((servicio) => {
    const nombre = normalizar(servicio?.nombre);
    return nombre && (nombre.includes(nombreBuscado) || nombreBuscado.includes(nombre));
  });
}

if (!servicioEncontrado) {
  return [
    {
      json: {
        ...datosCita,
        servicioEncontrado: false,
        mensaje: `No encontré el servicio "${datosCita.servicio || ''}".`,
      },
    },
  ];
}

const idServicio = obtenerId(servicioEncontrado);

if (!idServicio) {
  return [
    {
      json: {
        ...datosCita,
        servicioEncontrado: false,
        mensaje: 'El servicio fue encontrado, pero no contiene un ID válido.',
      },
    },
  ];
}

return [
  {
    json: {
      ...datosCita,
      servicioEncontrado: true,
      servicio: servicioEncontrado.nombre || datosCita.servicio,
      idServicio,
      duracionServicioMin:
        servicioEncontrado.duracion_minutos ??
        servicioEncontrado.duracionMinutos ??
        servicioEncontrado.duracionServicioMin ??
        null,
