  return [
    {
      json: {
        ...datosCita,
        staffEncontrado: false,
        requiereSeleccionStaff: false,
        profesionales: [],
        mensaje: 'No hay profesionales disponibles para este servicio.',
      },
    },
  ];
}

let staffSeleccionado = null;

if (datosCita.idStaff) {
  staffSeleccionado = activos.find(
    (persona) => String(obtenerIdStaff(persona)) === String(datosCita.idStaff),
  );

  if (!staffSeleccionado) {
    return [
      {
        json: {
          ...datosCita,
          staffEncontrado: false,
          requiereSeleccionStaff: true,
          profesionales,
          mensaje:
            'El profesional seleccionado no está disponible para este servicio. Selecciona otro profesional.',
        },
      },
    ];
  }
}

if (!staffSeleccionado && activos.length === 1) {
  staffSeleccionado = activos[0];
}

if (!staffSeleccionado && activos.length > 1) {
  return [
    {
      json: {
        ...datosCita,
        staffEncontrado: false,
        requiereSeleccionStaff: true,
        profesionales,
        mensaje: 'Hay varios profesionales disponibles. Debes seleccionar uno.',
      },
    },
  ];
}

return [
  {
    json: {
      ...datosCita,
      staffEncontrado: true,
      requiereSeleccionStaff: false,
      idStaff: obtenerIdStaff(staffSeleccionado),
      staffDetalle: staffSeleccionado,
      profesionales,
    },
  },
];

const datos = $input.first().json || {};
const profesionales = Array.isArray(datos.profesionales)
  ? datos.profesionales
  : [];

return [
  {
    json: {
      respuesta:
        datos.mensaje ||
        'Hay varios profesionales disponibles. Debes seleccionar uno.',
      requiereSeleccionStaff: true,
      profesionales,
      idCliente: datos.idCliente || null,
      servicio: datos.servicio || '',
      idServicio: datos.idServicio || null,
      fecha: datos.fecha || '',
      hora: datos.hora || '',
      sessionId: datos.sessionId || null,
    },
  },
];

const datosCita = $('Seleccionar staff').first().json || {};
const slots = [];

const agregarSlots = (valor) => {
  if (Array.isArray(valor)) {
    slots.push(...valor.filter(Boolean));
    return true;
  }

  return false;
};

for (const item of $input.all()) {
  const json = item.json;

  if (agregarSlots(json)) continue;
  if (!json || typeof json !== 'object') continue;
  if (agregarSlots(json.body)) continue;
  if (agregarSlots(json.data)) continue;
  if (agregarSlots(json.content)) continue;
  if (agregarSlots(json.items)) continue;
  if (agregarSlots(json.slots)) continue;
  if (agregarSlots(json.horariosDisponibles)) continue;

  if (json.inicio || json.fechaHoraInicio || json.horaInicio) {
    slots.push(json);
  }
}

const obtenerInicio = (slot) =>
  slot?.inicio || slot?.fechaHoraInicio || slot?.horaInicio || '';

const obtenerFinVisible = (slot) =>
  slot?.finVisible || slot?.fin_visible || slot?.fechaHoraFin || slot?.fin || null;

const formatearPartes = (valor) => {
  const fecha = new Date(valor);
  if (Number.isNaN(fecha.getTime())) return null;

  const partes = new Intl.DateTimeFormat('en-CA', {
    timeZone: 'America/Santiago',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    hour12: false,
  }).formatToParts(fecha);

  const obtener = (tipo) => partes.find((parte) => parte.type === tipo)?.value || '';
  let hour = obtener('hour');
  if (hour === '24') hour = '00';

  return {
    fecha: `${obtener('year')}-${obtener('month')}-${obtener('day')}`,
    hora: `${hour}:${obtener('minute')}`,
  };
};

const slotsValidos = slots
  .map((slot) => ({ slot, inicio: obtenerInicio(slot), partes: formatearPartes(obtenerInicio(slot)) }))
  .filter((item) => item.inicio && item.partes);

const horariosDisponibles = slotsValidos.map(({ slot, inicio, partes }) => ({
  inicio,
  finVisible: obtenerFinVisible(slot),
  hora: partes.hora,
}));

const fechaSolicitada = datosCita.fecha || '';
const horaSolicitada = datosCita.hora || '';

const encontrado = slotsValidos.find(
  ({ partes }) => partes.fecha === fechaSolicitada && partes.hora === horaSolicitada,
);

if (!encontrado) {
  return [
    {
      json: {
        ...datosCita,
        disponible: false,
        fechaHoraInicio: '',
        slot: null,
        horariosDisponibles,
        mensaje:
          horariosDisponibles.length > 0
            ? `El horario ${horaSolicitada} no está disponible.`
            : 'No hay horarios disponibles para esa fecha.',
      },
    },
  ];
}

return [
  {
    json: {
      ...datosCita,
      disponible: true,
      fechaHoraInicio: encontrado.inicio,
      slot: encontrado.slot,
      horariosDisponibles,
      mensaje: `El horario ${horaSolicitada} está disponible.`,
    },
  },
];

const cita = $input.first().json || {};
const contexto = $('Verificar horario solicitado').first().json || {};
const servicio = $('Buscar servicio solicitado').first().json || {};

const idCita =
  cita.idCita ||
  cita.id_cita ||
  cita.id ||
  cita.cita?.idCita ||
  cita.cita?.id ||
  '';

return [
  {
    json: {
      ...contexto,
      citaDetalle: cita,
      idCita,
      idCliente: contexto.idCliente || '',
      monto: Number(contexto.precioTotal ?? servicio.precioTotal ?? 0),
    },
  },
];

const pago = $input.first().json || {};
const datosPago = $('Preparar datos pago').first().json || {};

const idTransaccion =
  pago.idTransaccion ||
  pago.id_transaccion ||
  pago.id ||
  pago.transaccion?.idTransaccion ||
  '';

const idCita =
  pago.idCita ||
  pago.id_cita ||
  datosPago.idCita ||
  '';

const urlWebpay =
  pago.urlWebpay ||
  pago.urlPago ||
  pago.url ||
  '';

const tokenPago =
  pago.tokenPago ||
  pago.tokenWebpay ||
  pago.token_ws ||
  pago.token ||
  null;

const linkPago = idTransaccion
  ? `http://localhost:8080/api/pagos/webpay/redirigir/${idTransaccion}`
  : urlWebpay;

return [
  {
    json: {
      respuesta:
        'Tu reserva quedó pendiente de pago. Para confirmarla, abre el enlace y completa el pago.',
      estado: 'PENDIENTE_PAGO',
      idCita,
      idTransaccion: idTransaccion || null,
      linkPago: linkPago || null,
      urlPago: linkPago || null,
      tokenPago,
    },
  },
];

const data = $input.first().json || {};

const authorization = String(data.authorization || '').trim();

return [
  {
    json: {
      ...data,
      debugAuthorization: {
        existe: authorization.length > 0,
        empiezaConBearer: authorization.toLowerCase().startsWith('bearer '),
        largo: authorization.length,
        inicio: authorization.slice(0, 20),
        fin: authorization.slice(-10),
      },
    },
  },
];

const salidaIA = $input.first().json || {};
const contexto = $('Preparar prompt IA').first().json || {};

return [
  {
    json: {
      ...salidaIA,

      // Token recibido desde el Webhook.
      // No viene desde la IA, se recupera desde Preparar prompt IA.
      authorization: contexto.authorization || '',

      // Datos del sistema que deben conservarse.
      idClienteSistema: contexto.idCliente || '',
      idServicioSistema: contexto.idServicio || '',
      idStaffSistema: contexto.idStaff || '',
      servicioSistema: contexto.servicio || '',
      fechaSistema: contexto.fecha || '',
      horaSistema: contexto.hora || '',
      sessionId: contexto.sessionId || '',
      mensajeOriginal: contexto.mensaje || '',
      fechaActualChile: contexto.fechaActualChile || ''
    }
  }
];

const datos = $input.first().json || {};

const horariosDisponibles = Array.isArray(datos.horariosDisponibles)
  ? datos.horariosDisponibles
      .map((slot) => ({
        hora: slot.hora || '',
        inicio: slot.inicio || '',
        finVisible: slot.finVisible || null,
      }))
      .filter((slot) => slot.hora)
  : [];

return [
  {
    json: {
      respuesta:
        horariosDisponibles.length > 0
          ? `No tenemos la hora ${datos.hora} disponible, pero tenemos estas horas disponibles:`
          : `No tenemos la hora ${datos.hora} disponible y no hay otros horarios disponibles para esa fecha.`,

      disponible: false,

      horariosDisponibles,

      // Estos datos se devuelven para que React pueda reenviarlos
      // cuando el cliente elija otra hora.
      idCliente: datos.idCliente || '',
      idServicio: datos.idServicio || '',
      idStaff: datos.idStaff || '',
      servicio: datos.servicio || '',
      fecha: datos.fecha || '',
      sessionId: datos.sessionId || '',
    },
  },
];
